FAQ = [["How does Jump Trading use ChatGPT for quantitative research?","According to OpenAI's October 6, 2026 customer story, Jump Trading uses GPT-6 Astra-powered research agents to explore hypotheses, write and modify code, combine data sources and conduct longer-running quantitative studies, with people defining objectives and reviewing consequential outputs."],["Does Jump Trading use GPT-6 Astra?","Yes. OpenAI explicitly names GPT-6 Astra in its Jump Trading customer story. That public story is not a disclosure of Jump's complete model stack, deployment architecture or commercial contract."],["Can ChatGPT trade stocks automatically for Jump Trading?","The source describes agent-supported research and human review of research outputs, including possible trading signals. It does not establish that ChatGPT directly executes trades or controls live positions autonomously."],["Did GPT-6 Astra improve Jump Trading's returns?","No published return improvement, Sharpe ratio, hit-rate, P&L attribution, trading volume, benchmark sample or independently audited performance figure is supplied in the October 6 OpenAI customer story."],["What is long-horizon agentic quant research?","A human specifies a research question, tools, data environment and acceptance criteria; an AI agent can work across multiple steps and data sources, inspect intermediate findings and suggest hypotheses or code for human review."],["What is autoresearch in quantitative finance?","Autoresearch refers to iterative AI-assisted exploration of hypotheses, measurements and improvements. Jump's executive discusses it as a direction for the field; the story does not demonstrate a fully unsupervised production trading system."],["What are the biggest risks of AI agents in quantitative trading research?","Potential risks include look-ahead and survivorship bias, data leakage, multiple-testing overfitting, unrealistic transaction costs, unreliable tool actions, untraceable data provenance and excessive reliance on generated conclusions."],["How should a trading research team evaluate an AI agent?","Use point-in-time data, frozen baselines, walk-forward or truly out-of-sample tests, realistic costs and liquidity constraints, repeatability checks, complete tool audit logs and human approval before any production deployment. This is an SXF proposed evaluation framework, not a disclosed Jump Trading process."]]
BRIEF = "<section class=\"signal-layout shell\">\n  <article class=\"signal-brief\">\n    <p class=\"eyebrow\">SXF / SOURCE-VERIFIED CASE STUDY · REVIEWED NOVEMBER 8, 2026</p>\n    <p class=\"signal-summary\"><strong>Jump Trading is using GPT-6 Astra-powered agents in ChatGPT to expand quantitative research.</strong> In an OpenAI customer story published October 6, 2026, Jump's head of LLM R&amp;D, Lucas Baker, describes agents that can investigate longer, ambiguous questions across market, news and alternative data sources. Humans still define the objective, evaluation criteria, environment and acceptance process.</p>\n    <div class=\"signal-context\"><span>WHAT THIS REPORT ESTABLISHES</span><p>An <strong>AI-assisted research workflow</strong> with long-running tasks, agent coordination and human review of consequential findings. The case is <strong>not</strong> evidence of fully automated trading, proven market-beating returns, or audited gains from ChatGPT.</p></div>\n    <div class=\"signal-context\"><span>SXF EDITORIAL ASSESSMENT</span><p>The material innovation is the ability to explore and evaluate more research paths while retaining a controlled acceptance gate. In finance, producing more plausible hypotheses only helps when timestamp integrity, backtesting discipline, costs, reproducibility and permissions are rigorously checked.</p></div>\n  </article>\n  <aside class=\"source-card\">\n    <span class=\"source-card-label\">PRIMARY CASE SOURCE</span><strong>OpenAI · October 6, 2026</strong>\n    <p>Vendor-published customer interview featuring Jump Trading. Claims are attributed; SXF separates interpretation from disclosed evidence.</p>\n    <a href=\"https://openai.com/index/jump-trading/\" target=\"_blank\" rel=\"noopener noreferrer\">Read the OpenAI customer story ↗</a>\n    <p><small>Independent validation of trading performance: not published.</small></p>\n  </aside>\n</section>"
BODY = "<section class=\"signal-deep-dive shell jt-analysis\" data-sxf-jump-trading=\"2026-11-08\" aria-labelledby=\"jt-overview\">\n  <div class=\"intel-section-head\"><div><p class=\"eyebrow\">SXF / QUANTITATIVE AI RESEARCH ANALYSIS</p><h2 id=\"jt-overview\">Jump Trading, ChatGPT and GPT-6 Astra: the research workflow behind the headline.</h2></div><span>Verified November 8, 2026</span></div>\n  <p class=\"jt-deck\">What does <strong>Jump Trading's use of ChatGPT</strong> actually demonstrate? OpenAI's October 6, 2026 customer story describes the quantitative trading firm's use of <strong>GPT-6 Astra</strong> to investigate difficult research questions over extended agent workflows, including analysis across market data, news, events and alternative datasets. It does <em>not</em> publish investment returns or prove that ChatGPT trades automatically. This SXF analysis explains the reported workflow, what can be inferred, the missing evidence and the controls that would make <strong>agentic quantitative research</strong> useful in a financial environment. <a href=\"https://openai.com/index/jump-trading/\" target=\"_blank\" rel=\"noopener noreferrer\">Read OpenAI's original case study</a>.</p>\n  <div class=\"jt-facts\" aria-label=\"Case study at a glance\">\n    <div><span>COMPANY</span><strong>Jump Trading</strong><small>Quantitative trading and research</small></div>\n    <div><span>REPORTED MODEL</span><strong>GPT-6 Astra</strong><small>OpenAI / ChatGPT</small></div>\n    <div><span>USE CASE</span><strong>Long-horizon research</strong><small>Data analysis, coding and hypothesis evaluation</small></div>\n    <div><span>PUBLIC RETURNS DATA</span><strong>Not disclosed</strong><small>No independently verified P&amp;L or strategy hit rate</small></div>\n  </div>\n  <nav class=\"jt-toc\" aria-label=\"Article navigation\"><strong>Explore the analysis</strong>\n    <a href=\"#jt-what-happened\">What happened</a><a href=\"#jt-workflow\">Research workflow</a>\n    <a href=\"#jt-evidence\">Evidence limits</a><a href=\"#jt-finance\">Quant risks</a>\n    <a href=\"#jt-sxf-framework\">SXF methodology</a><a href=\"#jt-security\">Governance</a>\n    <a href=\"#jt-economics\">Cost evaluation</a><a href=\"#jt-questions\">FAQ</a>\n  </nav>\n\n  <section id=\"jt-what-happened\">\n    <h2>How is Jump Trading using ChatGPT and GPT-6 Astra?</h2>\n    <p>In the <a href=\"https://openai.com/index/jump-trading/\" target=\"_blank\" rel=\"noopener noreferrer\">October 6 OpenAI case study</a>, <strong>Lucas Baker, Head of LLM R&amp;D at Jump Trading</strong>, describes building the agents, orchestration systems and infrastructure that help quantitative researchers investigate hypotheses more broadly and deeply. The described shift is from asking a model for a short code snippet to giving one or several agents a longer research objective, a working environment and rules for assessing the value of interim results.</p>\n    <p>Quantitative research at Jump spans financial market data, news, events and alternative data. The goal is to identify useful predictive relationships in noisy, changing markets. The agent may write code, explore candidate analyses, compare intermediate findings against a human-set research question and redirect its next steps. Baker describes work that can run for days across multiple sources. That language is about the types of tasks the system can undertake; the article does not identify a measured average run duration or disclose proprietary datasets.</p>\n    <h3>Is this a new trading bot or a product launch?</h3>\n    <p><strong>No new consumer trading product is announced.</strong> This is an OpenAI-published <em>customer case study</em> about internal research methods. It describes GPT-6 Astra and ChatGPT as part of a research process, not a publicly available Jump-branded trading bot. It supplies no API integration blueprint, trading-execution architecture, strategy holdings or algorithm that readers can reproduce. Treat any claim that the case proves automated, profitable stock picking as unsupported.</p>\n    <h3>What is the role of the human researcher?</h3>\n    <p>According to Baker, a person defines the problem, data boundaries, research environment, what counts as a significant result and when to intervene. A human also reviews and accepts critical outputs, such as a proposed trading signal, before the firm's controlled systems can use them. OpenAI emphasizes that even its most advanced long-running workflows still involve check-ins. <strong>Research autonomy is not the same as autonomous trade authorization.</strong></p>\n  </section>\n\n  <section id=\"jt-workflow\">\n    <h2>How long-horizon AI agents change quantitative research</h2>\n    <p>The reported architecture is best understood as an <strong>iterative research loop</strong>, rather than one enormous prompt. The diagram below is an <em>SXF interpretation</em> of the activities described in OpenAI's case—not a diagram of Jump's undisclosed production systems.</p>\n    <ol class=\"jt-flow\">\n      <li><strong>01 · Frame a hypothesis.</strong> A researcher asks a testable question and specifies the assets, date ranges, decision horizons and measurement criteria.</li>\n      <li><strong>02 · Constrain the environment.</strong> Approved datasets, computation, tools and permissions are made available to the agent.</li>\n      <li><strong>03 · Explore in stages.</strong> The agent investigates data, writes analysis code and tests interim claims against the original criteria.</li>\n      <li><strong>04 · Compare and redirect.</strong> Subsequent steps may revise or discard a weak idea, rerun a check or coordinate with other agents.</li>\n      <li><strong>05 · Assemble auditable evidence.</strong> Findings, code, inputs, assumptions and failures are packaged for review.</li>\n      <li><strong>06 · Human acceptance.</strong> Qualified researchers decide whether an observation merits additional testing or integration into a controlled research pipeline.</li>\n    </ol>\n    <p>That loop can help with the volume of ideas examined, but every additional hypothesis increases the danger of finding apparent patterns by chance. More capable research automation therefore <strong>raises the bar for statistical discipline</strong> rather than reducing it. For a general explanation of tool-using AI systems, see <a href=\"/guides/what-is-agentic-ai/\">SXF's agentic AI guide</a>; for how persistent context can help or mislead an agent, see <a href=\"/research/ai-agent-memory/\">AI Agent Memory research</a>.</p>\n    <h3>Why GPT-6 Astra is relevant—but not the whole explanation</h3>\n    <p>OpenAI's <a href=\"https://developers.openai.com/api/docs/models/gpt-6-astra\" target=\"_blank\" rel=\"noopener noreferrer\">GPT-6 Astra technical documentation</a> describes a model aimed at complex reasoning, software engineering, tools and multistep professional work. Those capabilities make longer research loops technically plausible. But any observed business value also depends on the harness: data quality, permission boundaries, compute, tool execution, experiment logging, retrievability and human review. It is not possible to assign a portion of Jump's eventual research output to the base model from this public case alone. SXF maintains a <a href=\"/models/gpt-6-astra/\">GPT-6 Astra reference page</a> for model specifications, separate from this customer-story analysis.</p>\n  </section>\n\n  <section id=\"jt-evidence\">\n    <h2>What does the Jump Trading–OpenAI case study prove—and what is missing?</h2>\n    <p>The source is an official account of a named customer's experience, which is stronger than an anonymous rumor. But it is <strong>published by OpenAI, the model provider</strong>, not as a peer-reviewed comparison or a third-party audit. The following distinctions are essential for readers researching the financial impact of ChatGPT.</p>\n    <div class=\"jt-scroll\"><table class=\"jt-table\"><thead><tr><th>Question</th><th>What is publicly supported</th><th>What remains unknown</th></tr></thead><tbody>\n      <tr><th>Is Jump using GPT-6 Astra?</th><td>Yes; OpenAI names the model and attributes details to Jump's LLM R&amp;D lead.</td><td>Exact internal deployment, vendor mix and contract.</td></tr>\n      <tr><th>Can agents tackle longer tasks?</th><td>Baker describes days-long, multi-source work and autonomous intermediate redirection.</td><td>Measured median duration, task count, intervention rate or repeatability.</td></tr>\n      <tr><th>Does the work help research?</th><td>Jump reports broader exploration and a changed workflow.</td><td>Independent before/after evaluation and researcher-hours saved.</td></tr>\n      <tr><th>Are financial forecasts better?</th><td>No quantified evidence is published in this case.</td><td>Out-of-sample predictive power, drift, turnover or false-discovery rates.</td></tr>\n      <tr><th>Does the system earn more money?</th><td>No P&amp;L, risk-adjusted return or attributable profit is disclosed.</td><td>Live trading outcomes, costs and execution impact.</td></tr>\n      <tr><th>Does AI execute trades unattended?</th><td>Human acceptance and controlled integration of candidate signals are described.</td><td>No basis to conclude autonomous live trade execution by ChatGPT.</td></tr>\n    </tbody></table></div>\n    <div class=\"jt-note\"><strong>Evidence boundary:</strong> More autonomous research is a workflow claim; a superior investment strategy is an outcome claim. OpenAI's case supports the former as a customer-reported experience, but does not quantify the latter. SXF has not independently observed Jump's systems, performance or controls.</div>\n  </section>\n\n  <section id=\"jt-finance\">\n    <h2>Why quantitative finance is especially demanding for AI agents</h2>\n    <p>Markets are non-stationary: relationships may disappear when regimes, liquidity or incentives change. The statistical danger is not merely that an LLM writes a wrong explanation. An agent can generate a long list of plausible candidate factors, and a backtest can select winners <em>after</em> examining many noisy outcomes. Greater search throughput can magnify this selection effect.</p>\n    <h3>Look-ahead bias and point-in-time data</h3>\n    <p>If an agent tests a trading signal using information that would not have been available when a historical decision was made, it can produce an unrealistically strong result. The test should preserve when each data record and revision became usable—not only its event date. <a href=\"https://www.cfainstitute.org/insights/professional-learning/refresher-readings/2026/backtesting-and-simulation\" target=\"_blank\" rel=\"noopener noreferrer\">CFA Institute's Backtesting &amp; Simulation curriculum</a> highlights look-ahead and survivorship biases and advocates rolling-window techniques.</p>\n    <h3>Survivorship bias and alternative datasets</h3>\n    <p>Reconstructing an asset universe using only today's surviving securities can exclude failed or delisted names. News, event and alternative datasets also raise issues such as publication delay, corrections, missing observations and changing collection methods. Ask whether every input was available, licensed and valid at the simulated decision time.</p>\n    <h3>Multiple testing and overfitting</h3>\n    <p>An agent that tries hundreds of feature combinations may eventually find impressive historical returns by chance. Researchers should preregister or log proposed tests where feasible, keep genuinely untouched evaluation periods, and examine performance across rolling windows and different market regimes. Statistical significance without consideration of the search process can be misleading.</p>\n    <h3>Transaction costs, slippage, capacity and risk</h3>\n    <p>Even a predictive signal can fail economically once commissions, spreads, borrowing fees, market impact, turnover and portfolio limits are considered. <a href=\"https://www.cfainstitute.org/insights/professional-learning/refresher-readings/2026/active-equity-investing-strategies\" target=\"_blank\" rel=\"noopener noreferrer\">CFA Institute's active-equity material</a> treats data preparation, backtesting, strategy evaluation and portfolio construction as distinct steps, and explicitly flags unrealistic transaction costs and data-mining pitfalls.</p>\n    <p><strong>SXF conclusion:</strong> AI can make experiments cheaper to launch while making it easier to accumulate weak evidence. The research team must grow its validation discipline at least as quickly as its idea-generation capacity.</p>\n  </section>\n\n  <section id=\"jt-sxf-framework\">\n    <h2>SXF original analysis: a seven-gate review for AI-generated trading hypotheses</h2>\n    <p>We propose a <strong>seven-gate evaluation framework</strong> for teams considering AI-generated quantitative research. It is an original SXF editorial methodology inspired by established backtesting and AI-risk principles; <strong>it is not a description of Jump Trading's proprietary approval process</strong>, and it has not been validated as a commercial performance predictor.</p>\n    <div class=\"jt-scroll\"><table class=\"jt-table\"><thead><tr><th>Gate</th><th>Reviewer question</th><th>Minimum evidence artifact</th></tr></thead><tbody>\n      <tr><th>1. Hypothesis integrity</th><td>Was the rule or relationship stated before evaluating the final holdout?</td><td>Versioned hypothesis, target definition and experiment ID</td></tr>\n      <tr><th>2. Data provenance</th><td>Could every field really have been observed at decision time?</td><td>Point-in-time source map, revision history and licenses</td></tr>\n      <tr><th>3. Reproducibility</th><td>Can someone else rerun the complete pipeline?</td><td>Frozen code, dependencies, seeds and deterministic fixtures</td></tr>\n      <tr><th>4. Out-of-sample robustness</th><td>Does the effect survive time shifts, market regimes and untuned samples?</td><td>Walk-forward results, sensitivity checks and rejected trials</td></tr>\n      <tr><th>5. Economic realism</th><td>Is the signal still plausible after real trading frictions?</td><td>Turnover, spread, impact, liquidity and capacity assumptions</td></tr>\n      <tr><th>6. Operational containment</th><td>Can an agent read, write or launch only approved actions?</td><td>Permissions, logs, failure handling and test environment</td></tr>\n      <tr><th>7. Human acceptance</th><td>Did an accountable reviewer approve the evidence and risk?</td><td>Signed decision, limitations, owner and rollback criteria</td></tr>\n    </tbody></table></div>\n    <p><strong>Recommended gate logic:</strong> do not promote a candidate strategy merely because its summary score looks promising. A failure of point-in-time data integrity, reproducibility or authorization should block progression even if historical returns appear strong. That is a governance recommendation, not a report of Jump's actual policies.</p>\n    <h3>A worked example of how an AI backtest can mislead</h3>\n    <p>Suppose an agent proposes that a news-sentiment measure forecasts the next day's price change. A naive test might align the news with the day it describes, even when the article was released after the market close. The resulting apparent predictive relationship can be contaminated by <strong>information from the future</strong>. A sound test records the publication timestamp and the first tradable observation after that timestamp, replays decisions in chronological order, includes realistic costs and keeps a holdout period the agent never used to tune its rule.</p>\n    <p>The example is hypothetical, not a model of Jump's proprietary strategies. It shows why an agent should be graded on the integrity of the <em>research record</em>, not on how confidently it writes a backtest summary. Our <a href=\"/research/ai-agent-reliability/\">AI Agent Reliability framework</a> covers repeatability and failure measurement in more general agent systems.</p>\n  </section>\n\n  <section id=\"jt-security\">\n    <h2>Can human-in-the-loop controls make financial AI agents safer?</h2>\n    <p>Human review is important but insufficient if reviewers receive only an attractive final chart. A trustworthy research submission should include raw assumptions, source citations, data timestamps, execution traces, code diffs, tool errors, rejected hypotheses and the most recent test run. Observability needs to reveal the chain of evidence, not only the agent's final confidence statement.</p>\n    <p>OpenAI's story emphasizes secure working environments, clear task boundaries, steering, monitoring and human acceptance. Those themes are consistent with the <a href=\"https://www.nist.gov/itl/ai-risk-management-framework\" target=\"_blank\" rel=\"noopener noreferrer\">NIST AI Risk Management Framework</a>, which organizes AI governance into govern, map, measure and manage functions. NIST's framework is voluntary and cross-sector; it is a reference for risk design, not evidence that Jump follows every measure in it.</p>\n    <div class=\"jt-grid\">\n      <article><span>CONTROL 01</span><h3>Research/execution separation</h3><p>Keep hypothesis generation and data exploration distinct from privileged order-entry or portfolio-management systems. Candidate signals should not silently acquire trading authority.</p></article>\n      <article><span>CONTROL 02</span><h3>Read-only by default</h3><p>Constrain sensitive datasets, credentials, external network access and file writes. Explicitly approve any tool that changes a production system or protected research baseline.</p></article>\n      <article><span>CONTROL 03</span><h3>Auditable review</h3><p>Record the model and tool versions, experiment inputs, errors and reviewer decision so later analysts can reproduce or reject findings.</p></article>\n      <article><span>CONTROL 04</span><h3>Continuous revalidation</h3><p>Monitor drift, false discoveries, resource usage and failures after a model or data pipeline changes. Revalidate at defined checkpoints rather than assuming permanent reliability.</p></article>\n    </div>\n    <p>For public investors, <a href=\"https://syndication.finra.org/content/artificial-intelligence-ai-and-investment-fraud\" target=\"_blank\" rel=\"noopener noreferrer\">FINRA warns against relying solely on AI-generated information for investment decisions</a>. This is a general consumer warning, <strong>not</strong> a finding that Jump Trading violated any rule. SXF's <a href=\"/guides/ai-agent-security/\">AI Agent Security guide</a> expands on prompt injection, tools, sandboxing and permission scoping.</p>\n  </section>\n\n  <section id=\"jt-economics\">\n    <h2>Does long-running GPT-6 Astra quant research make economic sense?</h2>\n    <p>The case study does not disclose Jump's token consumption, compute footprint, contractual terms, researcher-hours saved, the number of research agents or any verified return on investment. OpenAI's <a href=\"https://developers.openai.com/api/docs/models/gpt-6-astra\" target=\"_blank\" rel=\"noopener noreferrer\">public GPT-6 Astra model page</a> provides developer-facing API unit prices, but an enterprise ChatGPT contract and a bespoke agent workflow need not be billed like a stand-alone API call. Therefore it would be misleading to estimate Jump's actual research costs from public API rates alone.</p>\n    <p><strong>SXF suggests comparing complete cost per accepted research finding</strong>, not merely dollars per million tokens. Include failed experiments, data and tooling, long-running compute, model and tool calls, reviewer time, repeated trials, observability and governance work. A cheaper agent loop that delivers more invalid hypotheses can cost more than a slower loop that produces fewer but better-audited candidates.</p>\n    <h3>Five metrics worth publishing in a future independent evaluation</h3>\n    <ul class=\"jt-metrics\">\n      <li><strong>Research throughput:</strong> accepted, independently reproducible hypotheses per analyst-month, not the raw count of generated ideas.</li>\n      <li><strong>Validation rate:</strong> share of proposed findings that pass untouched holdout and point-in-time checks.</li>\n      <li><strong>Human burden:</strong> reviewer minutes, corrections and escalation frequency per completed research artifact.</li>\n      <li><strong>Full economic cost:</strong> model calls, data access, tools, compute and review per accepted research outcome.</li>\n      <li><strong>Failure severity:</strong> unauthorized actions, data leaks, broken backtests or high-impact analytical errors.</li>\n    </ul>\n    <p>No such measurements are published in the October 6 story; these are proposed disclosure metrics, not invented results. SXF also maintains an <a href=\"/tools/ai-model-cost-calculator/\">AI model cost calculator</a> for public token-rate scenarios; it cannot infer Jump's private contract or end-to-end research economics.</p>\n  </section>\n\n  <section id=\"jt-implications\">\n    <h2>What Jump Trading's example means for research teams outside finance</h2>\n    <p>The generalizable insight is <strong>human-specified objectives plus agent exploration plus independently checkable acceptance</strong>. In biomedical, engineering or cybersecurity research, agents may similarly coordinate multiple tools and datasets while human domain experts decide whether a claimed result survives verification. Quant finance makes the stakes especially visible because mistaken correlations can translate into direct financial harm.</p>\n    <p>Jump's description also warns against assuming that longer autonomy is automatically better. A multi-day agent run may produce a richer artifact or simply more unverified branches. The operational advantage emerges when the team can trace each conclusion to original records, detect failed checks, reject unsupported claims and stop the workflow when the evidence is no longer credible.</p>\n    <p>For context, read <a href=\"/guides/what-is-agentic-ai/\">What Is Agentic AI?</a>, <a href=\"/research/ai-agent-reliability/\">AI Agent Reliability</a>, <a href=\"/guides/ai-model-benchmarks-explained/\">AI benchmark interpretation</a>, and <a href=\"/models/gpt-6-astra/\">GPT-6 Astra specifications</a>. Benchmarks for general agents should not be presented as proof of financial forecasting skill.</p>\n  </section>\n\n  <section id=\"jt-questions\">\n    <h2>Frequently asked questions: Jump Trading, OpenAI and ChatGPT</h2>\n    <h3>How does Jump Trading use ChatGPT?</h3><p>OpenAI says Jump uses GPT-6 Astra for longer-running, multi-source quantitative research: writing and improving code, exploring hypotheses, coordinating agent tasks and presenting findings for human review.</p>\n    <h3>Which OpenAI model is involved?</h3><p>The October 6 customer story explicitly names GPT-6 Astra. It does not disclose the firm's complete model roster or commercial agreement.</p>\n    <h3>Does ChatGPT execute Jump Trading's trades?</h3><p>The public case is about research and human-reviewed candidate trading signals. It does not establish autonomous live trade execution by ChatGPT.</p>\n    <h3>Does the Jump Trading case show higher investment returns?</h3><p>No quantified returns, Sharpe ratio, P&amp;L improvement, predictive accuracy figure or independently audited result is given in the OpenAI story.</p>\n    <h3>What is autoresearch in quantitative finance?</h3><p>It is an emerging approach in which agents repeatedly explore, test, revise and compare hypotheses under a specified goal and evaluation process. Jump describes this as a future research direction, not evidence of unsupervised production trading.</p>\n    <h3>Can AI agents reduce quant research time?</h3><p>They may help automate parts of coding and analysis, but a useful claim requires an appropriate comparison, including time spent validating, correcting and rejecting generated results. The Jump story does not publish a measured time-savings percentage.</p>\n    <h3>What risks are most important for AI quant research?</h3><p>Look-ahead bias, survivorship bias, overfitting, data leakage, unrealistic transaction costs, unreliable tools and missing human approval can undermine the apparent value of a generated strategy.</p>\n    <h3>How would SXF test an agentic quant research workflow?</h3><p>We propose seven review gates: hypothesis integrity, point-in-time data provenance, reproducibility, out-of-sample robustness, realistic economics, operational containment and human acceptance. This framework is SXF editorial guidance, not a disclosed Jump Trading internal process.</p>\n  </section>\n\n  <section id=\"jt-sources\">\n    <h2>Primary evidence, methodology and editorial disclosure</h2>\n    <p><strong>Last SXF verification: November 8, 2026.</strong> The named Jump Trading experience is derived from a single <em>vendor-published</em> OpenAI customer interview. External methodological references explain standard research and risk-assessment issues; they do not independently corroborate Jump's undisclosed business outcomes. Any SXF framework in this article is explicitly editorial interpretation. No investment recommendations, trading signals or guaranteed outcomes are provided.</p>\n    <ol class=\"jt-sources\">\n      <li><a href=\"https://openai.com/index/jump-trading/\" target=\"_blank\" rel=\"noopener noreferrer\">OpenAI — How Jump Trading is scaling quant research with ChatGPT</a> (October 6, 2026). Original customer account and researcher comments.</li>\n      <li><a href=\"https://developers.openai.com/api/docs/models/gpt-6-astra\" target=\"_blank\" rel=\"noopener noreferrer\">OpenAI API — GPT-6 Astra model reference</a>. Model capabilities and public API rates, not Jump's private deployment costs.</li>\n      <li><a href=\"https://www.cfainstitute.org/insights/professional-learning/refresher-readings/2026/backtesting-and-simulation\" target=\"_blank\" rel=\"noopener noreferrer\">CFA Institute — Backtesting &amp; Simulation (2026)</a>. Rolling-window tests, assumptions and common biases.</li>\n      <li><a href=\"https://www.cfainstitute.org/insights/professional-learning/refresher-readings/2026/active-equity-investing-strategies\" target=\"_blank\" rel=\"noopener noreferrer\">CFA Institute — Active Equity Investing: Strategies (2026)</a>. Quant strategy design, data and transaction-cost pitfalls.</li>\n      <li><a href=\"https://www.nist.gov/itl/ai-risk-management-framework\" target=\"_blank\" rel=\"noopener noreferrer\">NIST — AI Risk Management Framework</a>. Voluntary risk governance and operational assessment.</li>\n      <li><a href=\"https://syndication.finra.org/content/artificial-intelligence-ai-and-investment-fraud\" target=\"_blank\" rel=\"noopener noreferrer\">FINRA — Artificial Intelligence (AI) and Investment Fraud</a>. General caution about unsupported AI-driven financial claims.</li>\n    </ol>\n    <p><strong>Continue researching on SXF:</strong> <a href=\"/models/gpt-6-astra/\">GPT-6 Astra</a> · <a href=\"/research/ai-agent-reliability/\">Agent reliability</a> · <a href=\"/guides/ai-agent-security/\">Agent security</a> · <a href=\"/guides/ai-model-benchmarks-explained/\">Benchmark evidence</a> · <a href=\"/research/\">Research index</a>.</p>\n  </section>\n</section>"
CSS = "<style id=\"jt-editorial-css\">\n.jt-news .jt-analysis{margin:35px auto 58px}.jt-analysis section{max-width:1020px;margin:43px 0;scroll-margin-top:95px}.jt-analysis p,.jt-analysis li{line-height:1.8}.jt-analysis a{text-decoration:underline;text-underline-offset:3px}.jt-analysis section h2{font-size:clamp(1.5rem,2.35vw,2.08rem);margin:0 0 17px;line-height:1.3}.jt-analysis h3{font-size:1.12rem;line-height:1.45;margin:25px 0 10px}.jt-deck{max-width:930px;font-size:1.09rem;line-height:1.84!important;color:#c8d5e5}.jt-facts,.jt-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:25px 0}.jt-facts>div,.jt-grid>article{padding:20px;border:1px solid rgba(136,192,217,.28);border-radius:17px;background:linear-gradient(145deg,rgba(59,118,151,.17),rgba(8,14,25,.45))}.jt-facts span,.jt-grid span{display:block;font-size:.76rem;letter-spacing:.08em;color:#99e8dc;font-weight:800}.jt-facts strong{display:block;font-size:1.05rem;color:#f0f6fd;margin:9px 0 5px}.jt-facts small{color:#aabbcd;line-height:1.45}.jt-toc{display:flex;flex-wrap:wrap;gap:9px;margin:24px 0;padding:18px 20px;border-radius:16px;border:1px solid rgba(127,188,210,.29);background:rgba(29,58,76,.13)}.jt-toc strong{width:100%;margin-bottom:4px}.jt-toc a{border:1px solid rgba(135,200,216,.29);padding:7px 12px;border-radius:24px;text-decoration:none}.jt-flow{list-style:none;padding:0;margin:27px 0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.jt-flow li{border:1px solid rgba(112,186,215,.25);border-radius:16px;padding:18px;background:rgba(43,75,107,.12)}.jt-flow li strong{display:block;color:#9ce5d7;margin-bottom:6px}.jt-scroll{overflow-x:auto;border:1px solid rgba(140,186,226,.28);border-radius:15px;margin:25px 0}.jt-table{border-collapse:collapse;width:100%;min-width:745px;font-size:.9rem}.jt-table th,.jt-table td{vertical-align:top;text-align:left;padding:14px 16px;line-height:1.6;border-bottom:1px solid rgba(143,185,224,.17)}.jt-table thead th{background:#172c40;color:#e2f2ff}.jt-table tbody th{color:#a4eee1}.jt-note{background:rgba(86,169,158,.09);border-left:3px solid #85ecdc;padding:20px 23px;border-radius:0 14px 14px 0;margin:25px 0;line-height:1.8}.jt-grid h3{margin:9px 0 7px}.jt-grid p{margin:0}.jt-metrics,.jt-sources{padding-left:1.5rem}.jt-metrics li,.jt-sources li{margin:12px 0}.jt-news a:focus-visible{outline:2px solid #85ecdc;outline-offset:4px}@media(max-width:740px){.jt-facts,.jt-grid,.jt-flow{grid-template-columns:1fr}.jt-table{min-width:605px}.jt-analysis section{margin:34px 0}}\n</style>"

def enrich(page: str) -> str:
    """Transform the single thin RSS signal into the reviewed, original SXF analysis."""
    marker = 'data-sxf-jump-trading="2026-11-08"'
    if marker in page:
        return page
    required = ['class="intel-page signal-page"',
                '<h1>How Jump Trading is scaling quant research with ChatGPT</h1>',
                '<section class="signal-layout shell">',
                '<section class="signal-taxonomy shell">',
                '<meta name="twitter:card" content="summary" />']
    missing = [item for item in required if item not in page]
    if missing:
        raise ValueError(f"Jump Trading signal template changed: {missing}")
    page = page.replace('class="intel-page signal-page"',
                        'class="intel-page signal-page jt-news"', 1)
    page, count = re.subn(r'<title>.*?</title>', '<title>' + escape(TITLE) + '</title>',
                          page, count=1, flags=re.S)
    if count != 1:
        raise ValueError("Expected a single page title")
    for name, value in [('description', DESCRIPTION), ('og:title', TITLE),
                        ('og:description', DESCRIPTION), ('twitter:title', TITLE),
                        ('twitter:description', DESCRIPTION)]:
        kind = 'name' if name == 'description' else '(?:property|name)'
        pattern = r'(<meta ' + kind + r'="' + re.escape(name) + r'" content=")[^"]*(" />)'
        page, count = re.subn(pattern,
            lambda m: m.group(1) + escape(value, quote=True) + m.group(2),
            page, count=1)
        if count != 1:
            raise ValueError("SEO meta missing: " + name)
    page = page.replace('<meta name="twitter:card" content="summary" />',
        '<meta property="og:image" content="https://sxf.si/assets/og/sxf-ai-social.webp" />'
        '<meta property="og:image:alt" content="SXF analysis of agentic quantitative research at Jump Trading" />'
        '<meta name="twitter:card" content="summary_large_image" />'
        '<meta name="twitter:image" content="https://sxf.si/assets/og/sxf-ai-social.webp" />', 1)
    stylesheet = '<link rel="stylesheet" href="/intelligence.css" />'
    if stylesheet not in page:
        raise ValueError("Site style link absent")
    page = page.replace(stylesheet, stylesheet + '\n' + CSS, 1)
    match = re.search(r'<script type="application/ld\+json">(.*?)</script>', page, flags=re.S)
    if match is None:
        raise ValueError("Missing JSON-LD article")
    schema = json.loads(match.group(1))
    graph = schema['@graph']
    if len(graph) != 3:
        raise ValueError("Expected WebPage, Article, BreadcrumbList")
    graph[0].update(name=TITLE, description=DESCRIPTION,
                    breadcrumb={'@id': CANONICAL + '#breadcrumb'})
    graph[1].update(headline=H1, description=DESCRIPTION, dateModified='2026-11-08',
                    keywords=KEYWORDS, citation=SOURCES, isBasedOn=SOURCE,
                    about=[{'@type': 'Organization', 'name': 'Jump Trading'},
                           {'@type': 'SoftwareApplication', 'name': 'ChatGPT'},
                           {'@type': 'Thing', 'name': 'GPT-6 Astra'},
                           {'@type': 'Thing', 'name': 'Quantitative research'}])
    graph[2]['itemListElement'].append(
        {'@type': 'ListItem', 'position': 4,
         'name': 'Jump Trading and ChatGPT quantitative research analysis',
         'item': CANONICAL})
    graph.append({'@type': 'FAQPage', '@id': CANONICAL + '#faq',
        'mainEntity': [{'@type': 'Question', 'name': q,
                        'acceptedAnswer': {'@type': 'Answer', 'text': a}} for q, a in FAQ]})
    page = (page[:match.start()] + '<script type="application/ld+json">' +
            json.dumps(schema, ensure_ascii=False, separators=(',', ':')) +
            '</script>' + page[match.end():])
    page = page.replace('<h1>How Jump Trading is scaling quant research with ChatGPT</h1>',
                        '<h1>' + escape(H1) + '</h1>', 1)
    page, count = re.subn(r'<section class="signal-layout shell">.*?</section>',
                          lambda _: BRIEF, page, count=1, flags=re.S)
    if count != 1:
        raise ValueError("Signal brief replacement failed")
    page = page.replace('<section class="signal-taxonomy shell">',
                        BODY + '\n<section class="signal-taxonomy shell">', 1)
    page = page.replace('<a href="/topics/open-source-ai/">Open Source AI</a>',
                        '<a href="/topics/ai-agents/">AI Agents</a>', 1)
    page = page.replace('<div><span>MODELS</span><small>No named model detected</small></div>',
                        '<div><span>MODELS</span><a href="/models/gpt-6-astra/">GPT-6 Astra</a></div>', 1)
    if page.count(marker) != 1:
        raise ValueError("Missing or duplicated editorial marker")
    for reference in SOURCES:
        if reference not in page:
            raise ValueError("Unlinked source " + reference)
    return page
